#include <stdio.h>

int main() {
    int a = 6, b = 3;
    int result = 0;
    char op = '+';
    switch (op) {
        case '+':
            result = a + b;
            break;
        case '-':
            result = a - b;
            break;
        case '*':
            result = a * b;
            break;
    }
    printf("Result: %d\n", result);
    return 0;
}
